import{z as n,x as h,o as r,c as B,q as s,j as i,D as l,d as E,s as m,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"碰撞网格与视觉网格双导出","description":"","frontmatter":{"title":"碰撞网格与视觉网格双导出","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/marble-dual-mesh.md","filePath":"llm/marble-dual-mesh.md","lastUpdated":1791413859000}'),A={name:"llm/marble-dual-mesh.md"};function p(d,a,c,D,b,u){const t=h("Mermaid");return r(),B("div",null,[a[2]||(a[2]=s('<h1 id="碰撞网格与视觉网格双导出" tabindex="-1">碰撞网格与视觉网格双导出 <a class="header-anchor" href="#碰撞网格与视觉网格双导出" aria-label="Permalink to &quot;碰撞网格与视觉网格双导出&quot;">​</a></h1><div class="epigraph"><p>Marble 可导出碰撞网格——低保真、供粗物理仿真——以及尽量贴近高斯溅射观感的高质量网格。</p><footer>—— World Labs，Marble: A Multimodal World Model</footer></div><p>高斯溅射把世界画得像，却几乎不能直接丢进物理引擎：没有干净的封闭表面，接触点不稳定。三角网格能进引擎、能进 DCC，但一份网格很难同时满足两件事——碰撞要简单、保守、便宜；眼睛要密、贴外观、不怕三角数量。Marble 因此提供双导出：碰撞网格（collider）与高质量视觉网格。本篇只写为什么要两份、两份各自的合同，以及用错一份时会在仿真或画面上炸开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>游戏与机器人管线里，「网格」至少分裂成两条历史。渲染网格带着法线、材质、密 tessellation，目标是着色。碰撞网格是简化凸包、体素近似或低多边形封闭壳，目标是宽相与窄相检测在预算内完成。把渲染网格直接当碰撞体，是常见的事故：三角过多导致物理步进变慢，薄结构导致隧道穿透，非流形导致体积查询失败。把碰撞网格直接拿来渲染，是另一种事故：切面感、丢失栏杆空隙、门框变成实心块。</p><p><span class="marginnote">「宽相/窄相」是碰撞检测的两级流水线：宽相先用包围球、包围盒快速排除「绝不可能相撞」的物体对，窄相才对剩下的少数候选做三角形级的精确求交。碰撞网格的面数直接决定窄相开销——一堵墙用十万三角的渲染网格和用一个几十三角的凸包，每帧检测成本能差上几个数量级。</span></p><p>生成式世界同时踩中两个需求。创作者在 Marble 里看到的是溅射高保真外观，导出后希望在引擎里「看起来还是那个世界」，于是要视觉网格去逼近溅射。同时他们希望角色不掉出地板、子弹能打在墙上，于是要碰撞网格去近似占据。一份自动网格无法最优地服务两个损失函数：外观损失要细节，物理损失要简洁与封闭。双导出是承认这两个损失，而不是声称一种网格两头都好。</p><h3 id="合同必须分开写" tabindex="-1">合同必须分开写 <a class="header-anchor" href="#合同必须分开写" aria-label="Permalink to &quot;合同必须分开写&quot;">​</a></h3><p>碰撞合同：尽量封闭、尽量少面、略向外膨胀以免穿透，允许看起来丑。视觉合同：法线与轮廓尽量跟溅射走，允许非凸、允许更密，不保证物理稳定。若产品或管线只给一份「mesh.glb」，下游必须自己决定它是哪一种；双导出把决定提前到导出菜单。World Labs 的表述把碰撞写成 coarse physics，把高质量网格写成尽量匹配高斯溅射的视觉保真。</p><p><span class="marginnote">粗物理不是高精度接触力学。椅腿与地面的摩擦锥、软体、流体，都不在碰撞网格的合同里。它服务的是「不要穿过墙、地板能托住胶囊控制器」这一级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="同一世界-两套表面" tabindex="-1">同一世界，两套表面 <a class="header-anchor" href="#同一世界-两套表面" aria-label="Permalink to &quot;同一世界，两套表面&quot;">​</a></h3><p>从世界 \\(W\\)（通常以溅射为外观主本）抽出两套三角网格 \\(M_{\\mathrm{col}}\\) 与 \\(M_{\\mathrm{vis}}\\)。抽取可以共享占据估计，但简化策略分叉：</p> \\[M_{\\mathrm{col}}=\\mathrm{simp}_{\\mathrm{phys}}(S(W)), \\qquad M_{\\mathrm{vis}}=\\mathrm{extract}_{\\mathrm{vis}}(S(W)), \\]<p>其中 \\(S(W)\\) 是从粒子云估计的表面或体积。\\(\\mathrm{simp}_{\\mathrm{phys}}\\) 走体素化、凸分解、二次误差简化，优先封闭与低面数。\\(\\mathrm{extract}_{\\mathrm{vis}}\\) 保留褶皱、栏杆空隙、装饰线，面数可以高一个数量级。导出后在引擎里：渲染绑 \\(M_{\\mathrm{vis}}\\)（或继续用溅射渲染），刚体与角色控制器绑 \\(M_{\\mathrm{col}}\\)。</p><h3 id="碰撞宜保守-视觉宜贴合" tabindex="-1">碰撞宜保守，视觉宜贴合 <a class="header-anchor" href="#碰撞宜保守-视觉宜贴合" aria-label="Permalink to &quot;碰撞宜保守，视觉宜贴合&quot;">​</a></h3><p>设真实应挡的占据为 \\(\\mathcal{O}\\)。碰撞网格的内域 \\(\\mathrm{int}(M_{\\mathrm{col}})\\) 应满足 \\(\\mathcal{O}\\subseteq\\mathrm{int}(M_{\\mathrm{col}})\\) 的保守近似——略胖，以免胶囊从缝里漏。视觉网格则应对 \\(\\partial\\mathcal{O}\\) 的外观投影负责，甚至可以有不参与碰撞的装饰面。门洞在 \\(M_{\\mathrm{vis}}\\) 里应是洞，在 \\(M_{\\mathrm{col}}\\) 里若做成洞，控制器才能走进去；若碰撞体忘了开门洞，画面上有门，身体过不去——这是双网格没对齐的典型 bug，要对着同一坐标系检查开口。</p>',17)),(r(),i(o,null,{default:l(()=>[m(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E4%B8%96%E7%95%8C%20W%20%E6%BA%85%E5%B0%84%E4%B8%BB%E6%9C%AC%22%5D%20--%3E%20COL%5B%22%E7%A2%B0%E6%92%9E%E7%BD%91%E6%A0%BC%20%E4%BD%8E%E9%9D%A2%20%E5%B0%81%E9%97%AD%20%E7%95%A5%E8%83%96%22%5D%0A%20%20W%20--%3E%20VIS%5B%22%E8%A7%86%E8%A7%89%E7%BD%91%E6%A0%BC%20%E5%AF%86%20%E8%B4%B4%E5%A4%96%E8%A7%82%22%5D%0A%20%20COL%20--%3E%20PHY%5B%22%E7%89%A9%E7%90%86%E5%BC%95%E6%93%8E%20%E8%A7%92%E8%89%B2%20%E5%AD%90%E5%BC%B9%22%5D%0A%20%20VIS%20--%3E%20REN%5B%22%E6%B8%B2%E6%9F%93%20%E6%88%96%20DCC%20%E7%9C%8B%E7%89%87%22%5D%0A%20%20PHY%20--%3E%20PLAY%5B%22%E5%8F%AF%E8%B5%B0%E5%8F%AF%E6%92%9E%22%5D%0A%20%20REN%20--%3E%20PLAY%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"高质量网格「尽量」匹配溅射，不是逐像素保证。绒毛、半透明、视角高光在网格着色器里会丢。需要那一层保真时，渲染继续走溅射，网格只负责能在不支持粒子的工具里打开。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"从高斯到表面是一次推断。粒子密度高的地方像表面，低的地方像雾。视觉抽取会在密度脊上走 marching cubes 一类等值面，再投影颜色。碰撞抽取会先把密度场二值化成体素占据，再做膨胀与抽壳，避免雾状区域产生碎片三角去参加物理。机制分叉发生在二值化阈值与膨胀半径：视觉阈值跟外观走，碰撞阈值跟「能否托住角色」走。同一阈值两用，会要么碰撞碎，要么视觉肿。",-1)),(r(),i(o,null,{default:l(()=>[m(t,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E9%AB%98%E6%96%AF%E5%AF%86%E5%BA%A6%E5%9C%BA%22%5D%20--%3E%20T1%5B%22%E8%A7%86%E8%A7%89%E9%98%88%E5%80%BC%20%E6%B2%BF%E5%AF%86%E5%BA%A6%E8%84%8A%E5%8F%96%E7%AD%89%E5%80%BC%E9%9D%A2%22%5D%0A%20%20D%20--%3E%20T2%5B%22%E7%A2%B0%E6%92%9E%E9%98%88%E5%80%BC%20%E4%BA%8C%E5%80%BC%E5%8C%96%E4%B8%BA%E4%BD%93%E7%B4%A0%E5%8D%A0%E6%8D%AE%22%5D%0A%20%20T1%20--%3E%20MC%5B%22marching%20cubes%20%E4%BF%9D%E7%95%99%E8%A4%B6%E7%9A%B1%E4%B8%8E%E9%95%82%E7%A9%BA%22%5D%0A%20%20T2%20--%3E%20VOX%5B%22%E4%BD%93%E7%B4%A0%E8%86%A8%E8%83%80%20%E5%86%8D%E6%8A%BD%E5%A3%B3%22%5D%0A%20%20VOX%20--%3E%20CHK%7B%22%E5%B0%81%E9%97%AD%E4%B8%94%E4%BD%8E%E9%9D%A2%E6%95%B0%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20COL%5B%22%E7%A2%B0%E6%92%9E%E7%BD%91%E6%A0%BC%20%E7%BB%91%E7%89%A9%E7%90%86%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%22%7C%20VOX%0A%20%20MC%20--%3E%20VIS%5B%22%E8%A7%86%E8%A7%89%E7%BD%91%E6%A0%BC%20%E7%BB%91%E6%B8%B2%E6%9F%93%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">二值化就是给密度场划一条及格线：密度高于阈值的体素记为「实」，低于记为「空」。举个数字例子：门洞处密度恰为 0.48，碰撞阈值取 0.5 时它被判「空」，角色能穿门；若整图统一调高阈值到 0.4，同一条门缝可能被判「实」，门就焊死了。这就是「视觉阈值跟外观走、碰撞阈值跟托举走」不能混用的具体含义。</span></p><p>引擎侧的机制同样分叉。物理用简化网格做包围体层级，每步检测次数与面数、凸块数相关。渲染用视觉网格做光栅化，填充率与过度绘制相关。把 \\(M_{\\mathrm{vis}}\\) 丢进物理，层级建造时间与每步开销会按装饰细节爆炸。把 \\(M_{\\mathrm{col}}\\) 丢进高质量着色，法线从大平面来，高光会像塑料盒子。双导出让两边的加速结构各吃适合自己的输入。</p><h3 id="开口与层高要人工对表" tabindex="-1">开口与层高要人工对表 <a class="header-anchor" href="#开口与层高要人工对表" aria-label="Permalink to &quot;开口与层高要人工对表&quot;">​</a></h3><p>自动抽取不知道「这是门还是凹槽」。碰撞简化可能把栏杆封成实墙（安全但不可钻过），或把薄台阶漏成斜坡。视觉网格可能保留台阶却在碰撞里消失，角色原地踏步。机制上没有语义，只有几何启发式。导出后应用胶囊在门口、楼梯、栏杆处走一遍，把错的那一份网格单独修，而不是平均成第三份更糊的网格。</p><p><span class="marginnote">缩放实例时两份网格必须用同一变换。Composer 里放大过的世界，若只导出视觉、碰撞仍按生成时尺度，地面会托空或陷入。双导出是一对资产，不是两次互不相关的下载。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要发明一份「物理仿真论文」来支撑这组菜单。双网格是图形与游戏工业的老分工，Marble 把它接到生成世界上。没有公开的 arXiv 号描述 Marble 内部如何抽壳；能写的是产品合同与通用理由。需要可微物理、软体、精确摩擦时，应在专用仿真器里重建碰撞体，不要指望导出的 collider 是数字孪生。</p><p><span class="marginnote">初学者容易以为导出的碰撞体是世界的「数字孪生」，物理表现会和现实一致；实际上它只是一个精度到分米级的粗壳。堆叠的箱子会不会倒、子弹反弹角准不准，这类效果要靠专门调参甚至重建碰撞体；导出件只承诺「角色不会掉出世界、子弹不穿主墙」这一层底线。</span></p><p>视觉网格进 DCC 后可以再拓扑、再 UV，那已经离开生成器。碰撞网格进引擎后可以再凸分解。双导出是起点，不是终点。若目标平台只支持一种网格，要按平台的主任务选：看片选视觉，能走选碰撞，然后接受另一头变差。移动端尤其可能只敢用碰撞级面数去渲染，观感应预期切面，而不是回头怪生成器「没有桌面级溅射」。</p><p>与只导出溅射相比，双网格换来的是互操作：Unity、Unreal、Blender 认三角，不一定认你的溅射压缩格式。换来的代价是两份维护、开口对齐、以及视觉相对溅射的有损。若闭环完全在浏览器溅射渲染里、不需要物理，可以不导出网格。一旦有角色控制器或机械臂，缺碰撞体比缺视觉网格更致命——先保证不掉出世界，再谈密表面。</p><p>本篇不写 3DGS 的光栅化公式，也不写 Composer 如何拼大地图。双导出假定你已经有一个要带走的世界，并且清楚引擎里渲染与物理是两条组件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Marble 对网格提供双合同：碰撞用低保真壳做粗物理，视觉用高质量网格逼近溅射外观。</li><li>一份网格不能同时最优：密而碎的不能跑物理，简而胖的不能当最终画面。</li><li>碰撞宜保守封闭，视觉宜贴合；门口与楼梯必须两份对齐检查。</li><li>渲染可继续用溅射；网格负责互操作与物理，不是替代高保真粒子。</li><li>粗物理不等于高精度力学；没有产品内部抽壳的伪造论文号。</li><li>出处：World Labs Marble 博文中 collider meshes 与 high-quality meshes 的说明；对照 Kerbl 等 3DGS（2023）作为视觉主本，以及游戏引擎里渲染网格与碰撞网格的既有分工。</li></ul>',13))])}const M=n(A,[["render",p]]);export{_ as __pageData,M as default};
